        Assert.NotNull(channel);
        return channel!;
    }

    public void Dispose()
    {
        _client.Dispose();
        SqliteConnection.ClearAllPools();
        File.Delete(_dbPath);
        File.Delete(_dbPath + "-shm");
        File.Delete(_dbPath + "-wal");
        GC.SuppressFinalize(this);
    }
}

